using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.Linq;
using Office=Microsoft.Office.Core;
using PowerPoint=Microsoft.Office.Interop.PowerPoint;
namespace PowerPointIntelligence.AddIn {
 internal sealed class IndicatorSpec {
  internal string Kind="harvey",CustomSymbol=""; internal int Segments=4,Filled=1,CheckState=0,FilledColor=0xA65F25,UnfilledColor=0xFFFFFF,BackgroundColor=0xFFFFFF,OutlineColor=0x605040; internal float SizePt=36,Rotation=0;
  internal IndicatorSpec Copy(){return (IndicatorSpec)MemberwiseClone();}
  internal void Validate(){if(Kind!="harvey"&&Kind!="checkbox"||Segments<1||Segments>100||Filled<0||Filled>Segments||CheckState<0||CheckState>2||!Finite(SizePt)||SizePt<6||SizePt>720||!Finite(Rotation)||Rotation<0||Rotation>=360||new[]{FilledColor,UnfilledColor,BackgroundColor,OutlineColor}.Any(c=>c<0||c>0xFFFFFF)||CustomSymbol==null||CustomSymbol.Length>8||CustomSymbol.Any(Char.IsControl))throw new InvalidDataException("Invalid indicator settings.");}
  static bool Finite(float n){return !Single.IsNaN(n)&&!Single.IsInfinity(n);}
  internal IndicatorSpec Step(int delta){Validate();var s=Copy();if(s.Kind=="harvey")s.Filled=(int)Math.Max(0,Math.Min(s.Segments,(long)s.Filled+delta));else s.CheckState=((s.CheckState+delta%3)%3+3)%3;return s;}
  internal IndicatorSpec Shortcut(int key){Validate();if(key<0||key>8)throw new InvalidDataException("Numeric shortcut must be 0 through 8.");var s=Copy();if(s.Kind=="checkbox"){if(key>2)throw new InvalidDataException("Checkbox shortcut must be 0, 1 or 2.");s.CheckState=key;return s;}s.Filled=s.Segments<=8?Math.Min(key,s.Segments):(int)Math.Round(s.Segments*key/8.0,MidpointRounding.AwayFromZero);return s;}
 }
 internal static class IndicatorCodec {
  internal const string Namespace="urn:powerpoint-intelligence:indicator:v1";
  internal static string Encode(IndicatorSpec s){s.Validate();return new XElement(XName.Get("indicator",Namespace),new XAttribute("version",1),new XAttribute("kind",s.Kind),new XAttribute("segments",s.Segments),new XAttribute("filled",s.Filled),new XAttribute("check",s.CheckState),new XAttribute("fillColor",s.FilledColor),new XAttribute("emptyColor",s.UnfilledColor),new XAttribute("background",s.BackgroundColor),new XAttribute("outline",s.OutlineColor),new XAttribute("size",s.SizePt.ToString("R",CultureInfo.InvariantCulture)),new XAttribute("rotation",s.Rotation.ToString("R",CultureInfo.InvariantCulture)),new XAttribute("symbol",s.CustomSymbol)).ToString(SaveOptions.DisableFormatting);}
  internal static IndicatorSpec Decode(string xml){if(xml==null||xml.Length>4096)throw new InvalidDataException("Indicator metadata is missing or oversized.");try{using(var r=XmlReader.Create(new StringReader(xml),new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=4096})){var e=XElement.Load(r);string[] names={"version","kind","segments","filled","check","fillColor","emptyColor","background","outline","size","rotation","symbol"};if(e.Name!=XName.Get("indicator",Namespace)||e.Elements().Any()||e.Value!=""||e.Attributes().Any(a=>!a.IsNamespaceDeclaration&&!names.Contains(a.Name.LocalName)||!a.IsNamespaceDeclaration&&a.Name.NamespaceName!="")||names.Any(n=>e.Attribute(n)==null)||(string)e.Attribute("version")!="1")throw new InvalidDataException("Unsupported indicator metadata.");var s=new IndicatorSpec{Kind=(string)e.Attribute("kind"),Segments=I(e,"segments"),Filled=I(e,"filled"),CheckState=I(e,"check"),FilledColor=I(e,"fillColor"),UnfilledColor=I(e,"emptyColor"),BackgroundColor=I(e,"background"),OutlineColor=I(e,"outline"),SizePt=Single.Parse((string)e.Attribute("size"),CultureInfo.InvariantCulture),Rotation=Single.Parse((string)e.Attribute("rotation"),CultureInfo.InvariantCulture),CustomSymbol=(string)e.Attribute("symbol")};s.Validate();return s;}}catch(InvalidDataException){throw;}catch(Exception x){throw new InvalidDataException("Invalid indicator metadata.",x);}}
  static int I(XElement e,string n){return Int32.Parse((string)e.Attribute(n),CultureInfo.InvariantCulture);}
 }
 internal static class IndicatorElements {
  const string Tag="PPI_INDICATOR",Role="PPI_INDICATOR_ROLE";
  internal static bool IsIndicator(PowerPoint.Selection s){return s!=null&&s.Type==PowerPoint.PpSelectionType.ppSelectionShapes&&s.ShapeRange.Count==1&&s.ShapeRange[1].Tags[Tag]=="1";}
  static PowerPoint.Shape Selected(PowerPoint.Application app){if(app.ActiveWindow==null||!IsIndicator(app.ActiveWindow.Selection))throw new InvalidOperationException("Select one Intelligence indicator group.");var s=app.ActiveWindow.Selection.ShapeRange[1];Read(s);return s;}
  internal static IndicatorSpec Read(PowerPoint.Shape shape){if(shape==null||shape.Tags[Tag]!="1"||shape.Type!=Office.MsoShapeType.msoGroup||shape.GroupItems.Count<2||shape.GroupItems.Count>6)throw new InvalidDataException("Indicator group ownership is missing or unsupported; object preserved.");for(int i=1;i<=shape.GroupItems.Count;i++)if(shape.GroupItems[i].Tags[Role]!="1")throw new InvalidDataException("Indicator contains unowned shapes; object preserved.");var parts=XmlPartUpdates.AttachedParts(shape,IndicatorCodec.Namespace);if(parts.Length!=1)throw new InvalidDataException("Missing/ambiguous indicator metadata; canonicalMatches="+parts.Length+".");return IndicatorCodec.Decode(parts[0].XML);}
  internal static PowerPoint.Shape Insert(PowerPoint.Application app,string kind){var s=new IndicatorSpec{Kind=kind};s.Validate();var slide=Active(app);float w=app.ActivePresentation.PageSetup.SlideWidth,h=app.ActivePresentation.PageSetup.SlideHeight;if(w<s.SizePt||h<s.SizePt)throw new InvalidOperationException("Slide is too small for this indicator.");app.StartNewUndoEntry();return Render(slide,s,(w-s.SizePt)/2,(h-s.SizePt)/2,s.SizePt,s.SizePt);}
  static PowerPoint.Slide Active(PowerPoint.Application app){if(app==null||app.ActiveWindow==null||app.ActiveWindow.ViewType!=PowerPoint.PpViewType.ppViewNormal)throw new InvalidOperationException("Open a slide in Normal view.");return app.ActiveWindow.View.Slide as PowerPoint.Slide??throw new InvalidOperationException("Select a slide.");}
  internal static void Configure(PowerPoint.Application app,IndicatorSpec spec){spec.Validate();var old=Selected(app);var slide=Active(app);float l=old.Left,t=old.Top,w=old.Width,h=old.Height;var prior=Read(old);spec=spec.Copy();if(spec.Rotation==prior.Rotation)spec.Rotation=old.Rotation;if(spec.SizePt!=prior.SizePt){w=h=spec.SizePt;}float sw=app.ActivePresentation.PageSetup.SlideWidth,sh=app.ActivePresentation.PageSetup.SlideHeight;if(Single.IsNaN(l)||Single.IsNaN(t)||Single.IsInfinity(l)||Single.IsInfinity(t)||w<1||h<1||w>720||h>720||l<0||t<0||l+w>sw||t+h>sh)throw new InvalidDataException("Indicator bounds must fit inside the slide and remain at most 720 points.");app.StartNewUndoEntry();var replacement=Render(slide,spec,l,t,w,h);try{old.Delete();}catch(Exception error){throw new InvalidOperationException("Replacement created but original removal failed. Both retained; use Undo.",error);}replacement.Select();}
  internal static void Step(PowerPoint.Application app,int delta){Configure(app,Read(Selected(app)).Step(delta));}
  internal static void SetShortcut(PowerPoint.Application app,int key){Configure(app,Read(Selected(app)).Shortcut(key));}
  internal static void CycleSelected(PowerPoint.Application app){Step(app,1);}
  internal static void ConvertSelected(PowerPoint.Application app,string kind){var s=Read(Selected(app));s.Kind=kind;Configure(app,s);}
  internal static void SetValueSelected(PowerPoint.Application app,double value){if(Double.IsNaN(value)||Double.IsInfinity(value))throw new InvalidDataException("Indicator value must be finite.");var s=Read(Selected(app));if(s.Kind=="harvey"){if(value<0||value>1)throw new InvalidDataException("Harvey data value must be a fraction from 0 to 1.");s.Filled=(int)Math.Round(value*s.Segments,MidpointRounding.AwayFromZero);}else{if(value<0||value>2||value!=Math.Truncate(value))throw new InvalidDataException("Checkbox value must be 0, 1 or 2.");s.CheckState=(int)value;}Configure(app,s);}
  internal static void Edit(PowerPoint.Application app){var s=Read(Selected(app));using(var f=new System.Windows.Forms.Form{Text="Indicator settings",Width=420,Height=370,StartPosition=System.Windows.Forms.FormStartPosition.CenterScreen}){var n=new System.Windows.Forms.NumericUpDown{Left=20,Top=25,Minimum=1,Maximum=100,Value=s.Segments};var v=new System.Windows.Forms.NumericUpDown{Left=150,Top=25,Minimum=0,Maximum=s.Kind=="harvey"?100:2,Value=s.Kind=="harvey"?s.Filled:s.CheckState};var ok=new System.Windows.Forms.Button{Text="Apply",Left=260,Top=270,DialogResult=System.Windows.Forms.DialogResult.OK};f.Controls.AddRange(new System.Windows.Forms.Control[]{new System.Windows.Forms.Label{Text="Segments / filled or state",Left=20,Top=5,Width=240},n,v,ok});var size=new System.Windows.Forms.NumericUpDown{Left=20,Top=90,Minimum=6,Maximum=720,DecimalPlaces=1,Value=(decimal)s.SizePt};var rotation=new System.Windows.Forms.NumericUpDown{Left=150,Top=90,Minimum=0,Maximum=359,Value=(decimal)s.Rotation};var symbol=new System.Windows.Forms.TextBox{Left=20,Top=150,Width=260,MaxLength=8,Text=s.CustomSymbol};f.Controls.AddRange(new System.Windows.Forms.Control[]{new System.Windows.Forms.Label{Text="Size (pt) / rotation (degrees)",Left=20,Top=70,Width=300},size,rotation,new System.Windows.Forms.Label{Text="Optional custom checkbox symbol (8 characters)",Left=20,Top=130,Width=330},symbol});int[] colors={s.FilledColor,s.UnfilledColor,s.BackgroundColor,s.OutlineColor};string[] labels={"Filled","Unfilled","Background","Outline"};for(int i=0;i<4;i++){int index=i;var button=new System.Windows.Forms.Button{Text=labels[i],Left=20+i*90,Top=205,Width=85};button.Click+=(sender,args)=>{using(var dialog=new System.Windows.Forms.ColorDialog()){int c=colors[index];dialog.Color=System.Drawing.Color.FromArgb(c&255,(c>>8)&255,(c>>16)&255);if(dialog.ShowDialog(f)==System.Windows.Forms.DialogResult.OK)colors[index]=dialog.Color.R|(dialog.Color.G<<8)|(dialog.Color.B<<16);}};f.Controls.Add(button);}f.AcceptButton=ok;if(f.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;s.SizePt=(float)size.Value;s.Rotation=(float)rotation.Value;s.CustomSymbol=symbol.Text;s.FilledColor=colors[0];s.UnfilledColor=colors[1];s.BackgroundColor=colors[2];s.OutlineColor=colors[3];s.Segments=(int)n.Value;if(s.Kind=="harvey")s.Filled=(int)v.Value;else s.CheckState=(int)v.Value;s.Validate();Configure(app,s);}}
  static PowerPoint.Shape Render(PowerPoint.Slide slide,IndicatorSpec s,float l,float t,float w,float h){var created=new List<PowerPoint.Shape>();PowerPoint.Shape group=null;try{Action<PowerPoint.Shape,int,bool> style=(shape,color,outline)=>{created.Add(shape);shape.Tags.Add(Role,"1");shape.Fill.Solid();shape.Fill.ForeColor.RGB=color;shape.Line.Visible=outline?Office.MsoTriState.msoTrue:Office.MsoTriState.msoFalse;shape.Line.ForeColor.RGB=s.OutlineColor;};style(slide.Shapes.AddShape(Office.MsoAutoShapeType.msoShapeRectangle,l,t,w,h),s.BackgroundColor,false);style(slide.Shapes.AddShape(s.Kind=="harvey"?Office.MsoAutoShapeType.msoShapeOval:Office.MsoAutoShapeType.msoShapeRectangle,l,t,w,h),s.UnfilledColor,true);
   if(s.Kind=="harvey"&&s.Filled>0){if(s.Filled==s.Segments)style(slide.Shapes.AddShape(Office.MsoAutoShapeType.msoShapeOval,l,t,w,h),s.FilledColor,true);else{double angle=2*Math.PI*s.Filled/s.Segments;var b=slide.Shapes.BuildFreeform(Office.MsoEditingType.msoEditingCorner,l+w/2,t+h/2);for(int i=0;i<=100;i++){double a=-Math.PI/2+angle*i/100;b.AddNodes(Office.MsoSegmentType.msoSegmentLine,Office.MsoEditingType.msoEditingCorner,l+w/2+(float)Math.Cos(a)*w/2,t+h/2+(float)Math.Sin(a)*h/2);}b.AddNodes(Office.MsoSegmentType.msoSegmentLine,Office.MsoEditingType.msoEditingCorner,l+w/2,t+h/2);style(b.ConvertToShape(),s.FilledColor,false);}}
   if(s.Kind=="checkbox"&&s.CheckState>0){if(s.CustomSymbol!=""){var text=slide.Shapes.AddTextbox(Office.MsoTextOrientation.msoTextOrientationHorizontal,l,t,w,h);style(text,s.UnfilledColor,false);text.Fill.Visible=Office.MsoTriState.msoFalse;text.TextFrame.TextRange.Text=s.CustomSymbol;text.TextFrame.TextRange.Font.Size=Math.Min(w,h)*.65f;text.TextFrame.TextRange.Font.Color.RGB=s.FilledColor;text.TextFrame.TextRange.ParagraphFormat.Alignment=PowerPoint.PpParagraphAlignment.ppAlignCenter;text.TextFrame.VerticalAnchor=Office.MsoVerticalAnchor.msoAnchorMiddle;}else{Action<float,float,float,float> line=(x1,y1,x2,y2)=>{var z=slide.Shapes.AddLine(l+x1*w,t+y1*h,l+x2*w,t+y2*h);created.Add(z);z.Tags.Add(Role,"1");z.Line.ForeColor.RGB=s.FilledColor;z.Line.Weight=Math.Max(1,Math.Min(w,h)/14);};if(s.CheckState==1){line(.18f,.52f,.42f,.76f);line(.42f,.76f,.83f,.22f);}else{line(.22f,.22f,.78f,.78f);line(.78f,.22f,.22f,.78f);}}}
   group=slide.Shapes.Range(created.Select(x=>(object)x.Name).ToArray()).Group();group.Tags.Add(Tag,"1");var part=group.CustomerData.Add();if(!part.LoadXML(IndicatorCodec.Encode(s)))throw new InvalidDataException("Indicator metadata could not be persisted.");group.Rotation=s.Rotation;group.Name="Intelligence "+s.Kind;group.Select();return group;
  }catch(Exception error){bool failed=false;if(group!=null){try{group.Delete();}catch{failed=true;}}else foreach(var item in created)try{item.Delete();}catch{failed=true;}if(failed)throw new InvalidOperationException("Indicator creation failed and cleanup was incomplete. Use Undo.",error);throw;}}
 }
}



